package cz.mh.rallye.rallye_backend.simulation.api;
import java.util.*;import java.time.Instant;import java.net.URI;import java.nio.charset.StandardCharsets;
import com.fasterxml.jackson.annotation.JsonAnySetter;import tools.jackson.databind.JsonNode;
import org.springframework.web.bind.annotation.*;import org.springframework.http.*;import org.springframework.security.core.annotation.AuthenticationPrincipal;import jakarta.servlet.http.HttpServletResponse;
import cz.mh.rallye.rallye_backend.identity.application.AuthService.Principal;import cz.mh.rallye.rallye_backend.identity.application.AuthFailure;import cz.mh.rallye.rallye_backend.simulation.application.*;import cz.mh.rallye.rallye_backend.competition.domain.RaceEvaluator.Position;import cz.mh.rallye.rallye_backend.templates.application.TemplateDocumentHtml;
@RestController @RequestMapping("/api/v1/admin/race-simulations")
public class SimulationController {
 public record Body(JsonNode templateId,JsonNode templateVersion,JsonNode virtualStartAt,JsonNode version,JsonNode runId,JsonNode stageId,JsonNode code,JsonNode deltaMs,JsonNode mode,JsonNode latitude,JsonNode longitude,JsonNode accuracyMeters,JsonNode mockLocation,JsonNode throughSequence,JsonNode text){
  @JsonAnySetter public void unknown(String field,Object value){throw new IllegalArgumentException("Unsupported simulation field");}
  @Override public String toString(){return "SimulationBody[redacted]";}
  Map<String,JsonNode> fields(){var m=new HashMap<String,JsonNode>();String[] keys={"templateId","templateVersion","virtualStartAt","version","runId","stageId","code","deltaMs","mode","latitude","longitude","accuracyMeters","mockLocation","throughSequence","text"};JsonNode[] vals={templateId,templateVersion,virtualStartAt,version,runId,stageId,code,deltaMs,mode,latitude,longitude,accuracyMeters,mockLocation,throughSequence,text};for(int i=0;i<keys.length;i++)if(vals[i]!=null)m.put(keys[i],vals[i]);return m;}
 }
 public record CurrentStage(UUID simulationId,UUID runId,long version,SimulationView.ParticipantStage stage){}
 public record Dashboard(UUID simulationId,UUID runId,long version,String status,SimulationView.ClockView clock,Position position,SimulationView.GpsPreview gpsPreview,SimulationView.Dashboard dashboard){}
 private final SimulationService service;public SimulationController(SimulationService service){this.service=service;}
 @ModelAttribute void privacy(HttpServletResponse response){response.setHeader("Cache-Control","no-store");}
 private static AuthFailure invalid(){return new AuthFailure(400,"INVALID_REQUEST");}
 private static void fields(Body body,Set<String> required,Set<String> optional){if(body==null)throw invalid();var keys=body.fields().keySet();if(!keys.containsAll(required))throw invalid();var allowed=new HashSet<>(required);allowed.addAll(optional);if(!allowed.containsAll(keys))throw invalid();}
 private static long integer(JsonNode v,boolean signed){if(v==null||!v.isIntegralNumber()||!v.canConvertToLong()||!signed&&v.longValue()<0)throw invalid();return v.longValue();}
 private static String text(JsonNode v){if(v==null||!v.isString())throw invalid();return v.stringValue();}
 private static UUID uuid(JsonNode v){try{String value=text(v);UUID id=UUID.fromString(value);if(!id.toString().equalsIgnoreCase(value))throw invalid();return id;}catch(IllegalArgumentException e){throw invalid();}}
 private static double decimal(JsonNode v){if(v==null||!v.isNumber()||!Double.isFinite(v.doubleValue()))throw invalid();return v.doubleValue();}
 @PostMapping public ResponseEntity<SimulationView.View> create(@AuthenticationPrincipal Principal actor,@RequestHeader("Idempotency-Key")UUID key,@RequestBody Body body){fields(body,Set.of("templateId","templateVersion"),Set.of("virtualStartAt"));Instant start=null;if(body.virtualStartAt()!=null)try{start=Instant.parse(text(body.virtualStartAt()));}catch(java.time.DateTimeException e){throw invalid();}var result=service.create(actor,uuid(body.templateId()),integer(body.templateVersion(),false),key,start);return ResponseEntity.created(URI.create("/api/v1/admin/race-simulations/"+result.id())).body(result);}
 @GetMapping public SimulationService.Page list(@AuthenticationPrincipal Principal actor,@RequestParam(required=false)String status,@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="20")int size){return service.list(actor,status,page,size);}
 @GetMapping("/{id}") public SimulationView.View get(@AuthenticationPrincipal Principal actor,@PathVariable UUID id){return service.get(actor,id);}
 @GetMapping("/{id}/current-stage") public CurrentStage stage(@AuthenticationPrincipal Principal actor,@PathVariable UUID id){var s=service.get(actor,id);return new CurrentStage(s.id(),s.runId(),s.version(),s.currentStage());}
 @GetMapping("/{id}/dashboard") public Dashboard dashboard(@AuthenticationPrincipal Principal actor,@PathVariable UUID id){var s=service.get(actor,id);return new Dashboard(s.id(),s.runId(),s.version(),s.status(),s.clock(),s.position(),s.gpsPreview(),s.dashboard());}
 @PostMapping("/{id}/{command}") public SimulationView.View command(@AuthenticationPrincipal Principal actor,@PathVariable UUID id,@PathVariable String command,@RequestHeader("Idempotency-Key")UUID key,@RequestBody Body b){String op=switch(command){case "code-attempts"->"CODE";case "gps-attempts"->"GPS";case "stage-skips"->"SKIP";case "stage-completions"->"COMPLETE";case "clock-shifts"->"CLOCK_SHIFT";case "restarts"->"RESTART";case "restorations"->"RESTORE";case "closures"->"CLOSE";case "quiz-answers"->"QUIZ";default->throw new AuthFailure(404,"NOT_FOUND");};var required=new HashSet<>(Set.of("version","runId"));if(Set.of("CODE","GPS","SKIP","COMPLETE","QUIZ").contains(op))required.add("stageId");if(op.equals("CODE"))required.add("code");if(op.equals("CLOCK_SHIFT"))required.add("deltaMs");if(op.equals("RESTORE"))required.add("throughSequence");fields(b,required,Set.of());long version=integer(b.version(),false);UUID run=uuid(b.runId()),stage=b.stageId()==null?null:uuid(b.stageId());String code=b.code()==null?null:text(b.code());if(op.equals("QUIZ")){service.get(actor,id);throw new AuthFailure(501,"SIMULATION_QUIZ_UNSUPPORTED");}return service.mutate(actor,id,key,op,new SimulationService.Input(version,run,stage,code,b.deltaMs()==null?null:integer(b.deltaMs(),true),null,null,null,null,null,b.throughSequence()==null?null:integer(b.throughSequence(),false)));}
 @PutMapping("/{id}/position") public SimulationView.View position(@AuthenticationPrincipal Principal actor,@PathVariable UUID id,@RequestHeader("Idempotency-Key")UUID key,@RequestBody Body b){if(b==null)throw invalid();String mode=text(b.mode());var required=new HashSet<>(Set.of("version","runId","mode"));switch(mode){case "INPUT"->required.addAll(Set.of("latitude","longitude","accuracyMeters","mockLocation"));case "TARGET","OUTSIDE"->required.add("stageId");case "UNAVAILABLE"->{}default->throw invalid();}fields(b,required,Set.of());Boolean mock=null;if(b.mockLocation()!=null){if(!b.mockLocation().isBoolean())throw invalid();mock=b.mockLocation().booleanValue();}return service.mutate(actor,id,key,"POSITION",new SimulationService.Input(integer(b.version(),false),uuid(b.runId()),b.stageId()==null?null:uuid(b.stageId()),null,null,mode,b.latitude()==null?null:decimal(b.latitude()),b.longitude()==null?null:decimal(b.longitude()),b.accuracyMeters()==null?null:decimal(b.accuracyMeters()),mock,null));}
 @PostMapping("/coordinates/parse") public Object parse(@AuthenticationPrincipal Principal actor,@RequestBody Body body){fields(body,Set.of("text"),Set.of());return service.parse(actor,text(body.text()));}
 @GetMapping("/{id}/history") public SimulationService.HistoryPage history(@AuthenticationPrincipal Principal actor,@PathVariable UUID id,@RequestParam UUID runId,@RequestParam(defaultValue="0")long afterSequence,@RequestParam(defaultValue="50")int size){return service.history(actor,id,runId,afterSequence,size);}
 @DeleteMapping("/{id}") public ResponseEntity<Void> delete(@AuthenticationPrincipal Principal actor,@PathVariable UUID id,@RequestParam long version){service.delete(actor,id,version);return ResponseEntity.noContent().build();}
 @GetMapping("/{id}/files") public List<SimulationService.FileView> files(@AuthenticationPrincipal Principal actor,@PathVariable UUID id){return service.files(actor,id);}
 @GetMapping("/{id}/files/{fileName}") public ResponseEntity<byte[]> file(@AuthenticationPrincipal Principal actor,@PathVariable UUID id,@PathVariable String fileName){var c=service.file(actor,id,fileName);var r=ResponseEntity.ok().cacheControl(CacheControl.noStore()).header("X-Content-Type-Options","nosniff").header("Referrer-Policy","no-referrer").header("Content-Security-Policy",c.markdown()?TemplateDocumentHtml.csp():"default-src 'none'; sandbox").contentType(MediaType.parseMediaType(c.contentType()));if(c.pdf())r.header("Content-Disposition",ContentDisposition.attachment().filename(c.fileName(),StandardCharsets.UTF_8).build().toString());return r.body(c.bytes());}
 @ExceptionHandler(SimulationService.NotReady.class) ResponseEntity<ProblemDetail> notReady(SimulationService.NotReady failure){var problem=ProblemDetail.forStatus(409);problem.setProperty("code","SIMULATION_TEMPLATE_NOT_READY");problem.setProperty("errors",failure.report().errors());return ResponseEntity.status(409).body(problem);}
}
